library(tidyverse)

palmtrees &lt;- readr::read_csv('https://raw.githubusercontent.com/rfordatascience/tidytuesday/main/data/2025/2025-03-18/palmtrees.csv')

palmtrees |&gt;
  group_by(palm_tribe) |&gt;
  summarize(avg_leaves = mean(max_leaf_number, na.rm = TRUE)) |&gt;
  drop_na() |&gt;
  ggplot(aes(x = avg_leaves, y = fct_reorder(palm_tribe, avg_leaves))) +
  geom_col(fill = "darkgreen") +
  labs(
    title = "Average Maximum Leaf Number by Palm Tribe",
    x = "Average maximum number of leaves",
    y = "Palm tribe"
  ) +
  theme_minimal()
